"""bcrypt 5 upgrade: legacy hashes still verify; >72-byte passwords are rejected, not truncated."""

import pytest
from app.core.auth import AuthService

# Generated by passlib 1.7.4 + bcrypt 4.1.3 (the pre-upgrade stack).
LEGACY = "$2b$12$tDNMF.eaG/FMjmh02H6yIeHmE4ZNZZPNuEVsrf5sYn6crNKEhipQ."
# Same stack, 100-char password: silently truncated to 72 bytes at hash time.
LEGACY_LONG = "$2b$12$uCqLlqtonHhyf3sTBpyY4ehUIFgocGvCY3/RPKVOgbTuRpYD6NYta"


@pytest.fixture
def auth(db):
    return AuthService(db)


def test_legacy_hash_verifies(auth):
    assert auth.verify_password("correct horse battery", LEGACY)
    assert not auth.verify_password("wrong password", LEGACY)


def test_legacy_truncated_hash_still_verifies(auth):
    assert auth.verify_password("x" * 100, LEGACY_LONG)


def test_roundtrip_and_malformed_hash(auth):
    h = auth.get_password_hash("s3cretpass")
    assert h.startswith("$2b$") and auth.verify_password("s3cretpass", h)
    assert not auth.verify_password("s3cretpass", "not-a-hash")


def test_hash_rejects_over_72_bytes(auth):
    with pytest.raises(ValueError):
        auth.get_password_hash("x" * 73)
    auth.get_password_hash("x" * 72)


def test_api_rejects_long_password(client, parent_headers):
    r = client.post(
        "/api/v1/auth/reset",
        json={"token": "t", "password": "x" * 73},
        headers=parent_headers,
    )
    assert r.status_code == 422
    assert "72 bytes" in r.text


def test_user_service_create_and_authenticate(db):
    from app.schemas.user import UserCreate
    from app.services.user_service import UserService

    svc = UserService(db)
    svc.create_user(UserCreate(username="hasher", email="h@example.com", password="s3cretpass"))
    assert svc.authenticate_user("hasher", "s3cretpass") is not None
    assert svc.authenticate_user("hasher", "wrongpass1") is None
